  .event {
    --card-color: var(--color-ink) !important;

    background: var(--color-canvas);
    border: var(--border-light);
    box-shadow: none;
    break-inside: avoid;
    color: var(--color-ink);

    .avatar {
      --avatar-size: 2lh;
    }
  }

  /* Boards
  /* ------------------------------------------------------------------------ */

  .filters,
  .card--new,
  .cards__decoration,
  .card-columns:before,
  .cards--maybe:before {
    display: none;
  }

  .card-columns {
    border-block-start: var(--border-light);
    margin-block-end: 1ch;
    min-block-size: unset;
  }

  .cards--on-deck,
  .cards--doing {
    padding-inline: 0;
  }

  .cards--maybe {
    background: none;
    margin: 0;
    padding-inline: 1ch;

    .card__header {
      margin-inline: calc(-1 * var(--card-padding-inline));
    }

    .card__body {
      padding-block-start: calc(var(--card-padding-block) / 2);
    }
  }

  /* Card perma
  /* ------------------------------------------------------------------------ */

  .card-perma__notch,
  .card-perma__actions,
  .comment--new,
  .comments__subscribers,
  .card__meta-avatars--assignees > div > div:last-child,
  .steps > .step:last-child,
  .card__board-name .icon,
  div:has(> .card__tag-picker-button),
  .delete-card,
  .header--card .header__title {
    display: none;
  }

  .card-perma {
    display: block;
    inline-size: 100%;
    margin: 0 0 1lh;

    .card {
      aspect-ratio: unset;
    }

    .card__title {
      font-size: var(--text-x-large);
    }
  }

  .card-perma__bg {
    background: transparent;
    padding: 0;
  }

  .comments {
    --row-gap: 0;
    --comment-padding-inline: 1.4lh;

    padding-inline: 0;
  }

  .comment {
    --comment-max: none;

    border-block-end: var(--border-light);
  }

  .comment__content {
    background: none;
  }

  .comment__avatar {
    --btn-size: 2lh;

    margin-inline-start: 0;
  }

  .comment__author h3 {
    margin-inline: 0;
  }

  .comment__edit {
    display: none;
  }

  .comment__body {
    text-align: start;
  }

  .reactions {
    margin-block-start: 0;
  }

  /* Settings
  /* ------------------------------------------------------------------------ */

  .settings__user-filter .input {
    display: none;
  }

  .settings__panel {
    border: none;
    border-radius: 0;
    box-shadow: none;
    padding: 0;
    text-align: left;

    h2 {
      &:before,
      &:after {
        display: none;
      }
    }
  }

  .settings__panel--users {
    form:has(.btn--negative) {
      display: none;
    }

    .btn {
      background-color: transparent;
      border: none;
      color: var(--color-ink);
      opacity: 1;
    }

    .btn:not(:has(input:checked)) {
      opacity: 0;
    }
  }

  .settings__panel--entropy {
    display: none;
  }

  .settings__user-filter {
    background: none;
    margin: 0;
    padding: 0;

    /* Hide the "Everyone" switch */
    > li:first-child {
      display: none;
    }
  }
}

