require "application_system_test_case"
class LayoutCheckTest < ApplicationSystemTestCase
  include ActionView::RecordIdentifier
  test "check bounding rects" do
    sign_in_as(users(:david))
    card = cards(:logo) # has comments!
    card.reactions.create!(content: "🎉", reacter: users(:david))
    card.reactions.create!(content: "🔥", reacter: users(:kevin))

    visit board_url(card.board)
    find("##{dom_id(card.column)} .cards__expander").click

    rects = page.evaluate_script(<<~JS)
      (() => {
        const el = document.getElementById("#{dom_id(card, :article)}");
        const meta = el.querySelector(".card__meta").getBoundingClientRect();
        const boosts = el.querySelector(".card__boosts").getBoundingClientRect();
        const comments = el.querySelector(".card__comments").getBoundingClientRect();
        const cardRect = el.getBoundingClientRect();
        return { cardRect, meta, boosts, comments };
      })()
    JS
    puts "Board preview rects: #{rects.inspect}"
    assert rects["boosts"]["width"] > 0
    assert rects["boosts"]["height"] > 0
    assert rects["boosts"]["right"] <= rects["comments"]["left"] + 1, "boosts should not overlap comments"
    assert rects["meta"]["right"] <= rects["boosts"]["left"] + 1, "meta should not overlap boosts"

    visit card_url(card)
    perma_rects = page.evaluate_script(<<~JS)
      (() => {
        const container = document.getElementById("#{dom_id(card, :card_container)}");
        const reactions = container.querySelector(".reactions").getBoundingClientRect();
        const trigger = container.querySelector(".reactions__trigger").getBoundingClientRect();
        const notch = container.querySelector(".card-perma__notch--bottom").getBoundingClientRect();
        return { reactions, trigger, notch };
      })()
    JS
