    assert perma_rects["trigger"]["width"] > 20
    assert perma_rects["trigger"]["height"] > 20
    assert perma_rects["reactions"]["bottom"] <= perma_rects["notch"]["top"] + 1, "reactions should not overlap bottom notch"
  end
end
